{
  "simulation_specification": {
    "simulated_user_config": {
      "language": "de",
      "prompt": {
        "prompt": "You are a German speaking customer in Austria contacting Unica. You want a Kfz car insurance quote. Reply briefly and naturally in German. Give only the detail that is asked, do not list everything at once. Use exactly these facts when asked: Deckung ist Vollkasko; Alter 42; Motorleistung 110 kW; Wohnort Wien; Fahrzeugwert 25000 Euro; 8 schadenfreie Jahre; ein Lenker; keine besonderen Wuensche. You want the estimate now and you do NOT want to be passed to a specialist. Your name is Max Mustermann and your phone number is 0660 1234567; give them when asked. After you receive the price and the closing, say goodbye to end the conversation."
      }
    }
  },
  "new_turns_limit": 30
}

parameters.jsCode:
const runs = $input.all();
const out = [];
for(var r=0;r<runs.length;r++){
  var conv = runs[r].json.simulated_conversation || [];
  var questions=[], toolCalls=[], toolResults=[];
  for(var i=0;i<conv.length;i++){
    var t=conv[i];
    if(t.role==="agent" && t.message){ questions.push(t.message); }
    if(t.tool_calls){ for(var j=0;j<t.tool_calls.length;j++){ var tc=t.tool_calls[j]; var p={}; try{ p=JSON.parse(tc.params_as_json||"{}"); }catch(e){ p={raw:tc.params_as_json}; } toolCalls.push({tool:tc.tool_name, params:p}); } }
    if(t.tool_results){ for(var k=0;k<t.tool_results.length;k++){ var tr=t.tool_results[k]; var v=tr.result_value; try{ v=JSON.parse(tr.result_value); }catch(e){} toolResults.push(v); } }
  }
  var quote=null;
  for(var m=toolResults.length-1;m>=0;m--){ if(toolResults[m] && toolResults[m].estimate){ quote=toolResults[m]; break; } }
  var finalParams = toolCalls.length? toolCalls[toolCalls.length-1].params : null;
  out.push({ json: {
    run: r+1,
    num_agent_turns: questions.length,
    agent_questions: questions,
    tool_calls: toolCalls,
    collected_final: finalParams,
    quote: quote ? { product: (quote.recommended_product? quote.recommended_product.ProductName:null), estimate: quote.estimate, low: (quote.indicative_range?quote.indicative_range.low:null), high: (quote.indicative_range?quote.indicative_range.high:null) } : null
  } });
}
return out;
